async function startAdvanced(){const token=await window.EASync?.getIdToken();if(!token)throw new Error('not-configured');micStream=await navigator.mediaDevices.getUserMedia({audio:true});const r=await backend('session',{context:{...context,sharedLesson:shared},limits:{dailyMinutes:settings.advancedDailyMinutes,monthlyMinutes:settings.monthlyAdvancedMinutes},hebrewHelp:settings.hebrewHelp,retainTranscript:settings.retainTranscript});sessionId=r.sessionId;pc=new RTCPeerConnection();const audio=document.createElement('audio');audio.autoplay=true;pc.ontrack=e=>audio.srcObject=e.streams[0];micStream.getTracks().forEach(t=>pc.addTrack(t,micStream));dc=pc.createDataChannel('oai-events');dc.onopen=()=>{status('listening','המורה המתקדם מחובר');sendAdvancedInstruction('Begin the greeting phase. Use the approved lesson context and ask only one question. Wait for the deterministic validator before saying an answer is correct.')};dc.onmessage=handleAdvancedEvent;const offer=await pc.createOffer();await pc.setLocalDescription(offer);const sdp=await fetch('https://api.openai.com/v1/realtime/calls',{method:'POST',headers:{Authorization:`Bearer ${r.clientSecret}`,'Content-Type':'application/sdp'},body:offer.sdp});if(!sdp.ok)throw new Error('backend');await pc.setRemoteDescription({type:'answer',sdp:await sdp.text()})}
function sendAdvancedInstruction(text){if(dc?.readyState==='open')dc.send(JSON.stringify({type:'response.create',response:{instructions:text}}))}
