function startPlacement(){let modal=$('#adaptivePlacementModal');if(!modal){modal=document.createElement('div');modal.className='modal';modal.id='adaptivePlacementModal';modal.setAttribute('role','dialog');modal.setAttribute('aria-modal','true');modal.innerHTML='<article class="panel"><div class="panelhead"><h2>מבדק פתיחה ידידותי</h2><button class="close" data-close aria-label="סגירה">×</button></div><div id="adaptivePlacementBody"></div></article>';document.body.append(modal);modal.querySelector('[data-close]').onclick=()=>window.EAApp.closeModal(modal)}const challenges=Adaptive.SKILLS.flatMap((skill,i)=>[{skill,level:1,q:['בחרו מילה באנגלית','איזו מילה שמעתם?','אמרו או בחרו: hello','בחרו את ההגייה הקרובה ל־cat','בנו משפט קצר','קראו ובחרו: red','מה פירוש apple?'][i],correct:['cat','hello','hello','cat','I am happy','red','תפוח'][i],wrong:['pizza','night','goodbye','dog','happy am','blue','כלב'][i]},{skill,level:3,q:'ניסיון קצת יותר מאתגר',correct:['This is a cat','Nice to meet you','My name is Maya','three','I like apples','The sky is blue','I am happy'][i],wrong:['banana','noise','pizza','ten','apple','green','sad'][i]}]);const results=[],failed=new Set(),body=modal.querySelector('#adaptivePlacementBody');let index=0;const draw=()=>{while(index<challenges.length&&failed.has(challenges[index].skill))index++;if(index>=challenges.length){window.EAApp.completePlacement(results);body.innerHTML='<div class="celebrate"><div class="trophy">🌟</div><h3>סיימנו! מצאנו נקודת התחלה נעימה.</h3><button class="primary" id="placementDone">חזרה</button></div>';body.querySelector('#placementDone').onclick=()=>{window.EAApp.closeModal(modal);$('#adaptiveDashboard')?.remove();renderAdaptiveDashboard()};return}const c=challenges[index];body.innerHTML=`<p><strong>${Adaptive.SKILL_HE[c.skill]}</strong> • שלב ${c.level}</p><h3>${c.q}</h3><div class="answer-buttons"></div><button class="btn" id="placementStop">מספיק להיום</button>`;for(const answer of [c.correct,c.wrong].sort(()=>Math.random()-.5)){const b=document.createElement('button');b.className='option';b.textContent=answer;b.onclick=()=>{const correct=answer===c.correct;results.push({skill:c.skill,level:c.level,correct});if(!correct)failed.add(c.skill);index++;draw()};body.querySelector('.answer-buttons').append(b)}body.querySelector('#placementStop').onclick=()=>{window.EAApp.completePlacement(results);index=challenges.length;draw()}};draw();window.EAApp.openModal(modal)}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}

